// Super simple auth - just username/password
import { supabase } from '../lib/supabase';

export interface User {
  id: number;
  username: string;
  password: string;
}

// Mock users for when no Supabase
let users: User[] = [
  { id: 1, username: 'demo', password: 'demo123' }
];
let loggedInUser: User | null = null;

export const authService = {
  signUp: async (username: string, password: string) => {
    console.log('📝 Sign up:', username);

    if (supabase) {
      // Use real Supabase table
      try {
        // Check if username exists
        const { data: existing } = await supabase
          .from('simple_users')
          .select('*')
          .eq('username', username)
          .single();

        if (existing) {
          return { success: false, error: 'Username taken' };
        }

        // Create new user
        const { data, error } = await supabase
          .from('simple_users')
          .insert({ username, password })
          .select()
          .single();

        if (error) {
          return { success: false, error: error.message };
        }

        loggedInUser = data;
        return { success: true, user: data };
      } catch (err) {
        return { success: false, error: 'Failed to sign up' };
      }
    } else {
      // Use mock storage
      if (users.find(u => u.username === username)) {
        return { success: false, error: 'Username taken' };
      }

      const newUser = {
        id: users.length + 1,
        username,
        password
      };

      users.push(newUser);
      loggedInUser = newUser;
      return { success: true, user: newUser };
    }
  },

  signIn: async (username: string, password: string) => {
    console.log('🔐 Sign in:', username);

    if (supabase) {
      // Use real Supabase table
      try {
        const { data, error } = await supabase
          .from('simple_users')
          .select('*')
          .eq('username', username)
          .eq('password', password)
          .single();

        if (error || !data) {
          return { success: false, error: 'Wrong username/password' };
        }

        loggedInUser = data;
        return { success: true, user: data };
      } catch (err) {
        return { success: false, error: 'Failed to sign in' };
      }
    } else {
      // Use mock storage
      const user = users.find(u => u.username === username && u.password === password);

      if (!user) {
        return { success: false, error: 'Wrong username/password' };
      }

      loggedInUser = user;
      return { success: true, user };
    }
  },

  getCurrentUser: () => loggedInUser,

  signOut: () => {
    loggedInUser = null;
  }
};

// Stub exports for missing services to prevent import errors
export interface DocumentData {
  id: string;
  title: string;
  content: string;
  tags?: string[];
  status?: string;
  complexity?: string;
  originalTitle?: string;
  summary?: string;
  simplificationLevel?: number;
  pageCount?: number;
  fileSize?: number;
  type?: string;
  createdAt?: string;
  originalContent?: string;
  simplifiedContent?: string;
}

export interface ChatMessageData {
  id: string;
  content: string;
  sender: 'user' | 'ai';
}

export const documentService = {
  getAllDocuments: async () => [],
  getDocument: async (id: string) => ({ document: null, error: null }),
  getUserDocuments: async () => ({ documents: [], error: null }),
  createDocument: async (data: any) => null,
  updateDocument: async (id: string, data: any) => null,
  deleteDocument: async (id: string) => false,
};

export const chatService = {
  getMessages: async (documentId: string) => [],
  sendMessage: async (documentId: string, content: string) => null,
};
